"""Write bounded physical reviews and exact batch results from audited evidence."""
import csv,hashlib,json
from pathlib import Path
B=Path(__file__).resolve().parent;ROOT=B.parent
rows=list(csv.DictReader((B/'queue.csv').open(encoding='utf-8',newline='')))
status={r['sample_id']:r for r in csv.DictReader((ROOT/'shared-catalogues'/'TARGET-STATUS.csv').open(encoding='utf-8',newline=''))}
assert [r['sample_id'] for r in rows]==[f'Q{i:03d}' for i in range(11,21)]

# Each entry is an interpretation of the selected eclipse claim, not a global
# exclusion of variability or binarity. Numbers below are traced in target
# lead-inventory.json, lead-q011-clock.json, WCS products, and helper-numeric.json.
R={
'Q011':dict(verdict='PROBABLE',depth='6.5',finding='Seven narrow raw SAP losses in S29 and S69 have measured minima at 2089.5918, 2096.1545, 2109.2588, 3184.6399, 3191.2002, 3197.7466, and 3204.3092 BTJD. Local raw depths are 6.3–6.8 ppt. The sequence fits a 6.557-day photometric spacing with 5.75-minute residual RMS. A separate fixed 3×3 sky-subtracted WCS aperture recovers 3.7–5.2 ppt losses at all seven occasions. The three fully sampled extra windows at half that spacing, 2092.8707, 2105.9851, and 3201.0311, have local SAP losses +0.11, −0.17, and +0.14 ppt against about 6.5 ppt events; their core counts are 17, 15, and 44.',interpretation='Real repeated eclipse-like losses are strongly supported. The 6.557-day interval is a photometric step; equal-depth alternating kinds allow a 13.114-day orbital period. Gaia SB2 P=35.673188 d does not provide source-specific conjunction timing for these losses. WCS difference peaks lie close to the target, but Gaia DR3 2319058524800146688 (G=15.02) is only 21.74 arcsec away and has enough approximate G flux for a deep blended eclipse. Target attribution and orbital geometry are unresolved.',limitations='Orbital period, eclipse kind, target ownership, and compatibility with the Gaia SB2 orbit are unresolved; no precision period or primary epoch is adopted.',next='Obtain resolved photometry or source-specific PSF difference fitting for the 21.74-arcsec neighbor, then test 6.557 versus 13.114 d and conjunction geometry.'),
'Q012':dict(verdict='REFUTED',depth='',finding='Raw S12 and S39 show continuously cycling asymmetric 1.5–3-day waves: selected dips near 1630.64, 1633.68, 1635.22 and 2362.70–2370.31 are successive wave troughs. S67, S93, and S102 retain changing, multi-hump modulation. S94 has a broad trend down to the 3874.88 flag near an orbit boundary rather than a discrete repeated eclipse.',interpretation='The selected detector deficits follow smooth evolving variability and baseline structure, with no isolated recurring eclipse shape. This refutes the selected eclipse interpretation; astrophysical non-eclipse variability remains possible.',limitations='No orbital period, eclipse depth or source-specific geometry is measured from these troughs. This does not exclude a different binary signal.',next='Characterize the smooth short-timescale variability separately if scientifically useful.'),
'Q013':dict(verdict='REFUTED',depth='',finding='Across 37 available sectors the flagged windows sit amid large orbit-related ramps, resets and brightenings. The largest selected deficit, 62 ppt at 2047.83 in S27, falls immediately before a 2048.080–2049.170 d gap and a flux-level change. The S68 3162.61 broad flag occurs in another strong ramp; flagged brightenings in S27/S38 reach tens of ppt in the same unstable context.',interpretation='The selected dip statistics are produced by nonstationary baseline and orbit-edge behavior rather than repeated isolated eclipses.',limitations='This is a refutation of selected windows, not a proof that the target cannot eclipse at some other time. No reliable eclipse clock is measured.',next='Only revisit with a reduction that stabilizes orbit edges and yields repeated isolated shapes.'),
'Q014':dict(verdict='REFUTED',depth='',finding='S94 3874.87 and S104 4197.35 flags align to within about 0.05 d with Q016 flags in the same sectors. S103 4166.24 begins just after the 4165.080–4166.129 d gap, and S101 4112.57 occurs on a falling trend before the 4113.149–4114.556 d gap. Raw traces show curved orbit-scale ramps and abrupt resets, not a coherent repeated eclipse shape.',interpretation='Positive shared-timing, gap and baseline evidence refutes the selected eclipse interpretation.',limitations='No source-specific eclipse timing or geometry exists for these flags; no global binary exclusion is inferred.',next='If revisited, compare background and detector systematics on the same cadences before timing any putative event.'),
'Q015':dict(verdict='REFUTED',depth='',finding='Many raw SAP narrow losses recur at approximately 2.89-day spacing, but their source is displaced. In independent S41/S55/S82 WCS difference maps the loss peaks are at pixels (10,2–3), (2,10), and (3,9), while the queued target lies near (5.55,5.49), (5.01,5.90), and (6.00,5.00). Peak losses are 559–962 e/s per pixel, while the target central pixel changes range about −9 to +5 e/s. The changing cutout orientation maps each loss peak to Gaia DR3 2186586958712163712 (G=9.379), about 99 arcsec from the queued G=11.336 source.',interpretation='The repeated signal is a genuine follow-up lead for the bright neighboring source, but the selected attribution to TIC 352610732 is positively refuted.',limitations='The contaminant’s unique orbital period and catalogue novelty are unestablished. The result does not exclude separate variability of the queued target.',next='Review Gaia DR3 2186586958712163712 as its own source using a centered aperture and source-specific catalogue checks.'),
'Q016':dict(verdict='REFUTED',depth='',finding='The S94 3874.82 and S104 4197.37 flags occur at essentially the same times as Q014 S94/S104 flags. In S101 the 4107.75 selection follows a 4107.039–4107.269 d gap and raw reset; S102 4145.06 lies at the end of a rising orbit-scale trend before the 4145.511–4146.249 d gap. The full raw traces do not repeat a discrete eclipse profile.',interpretation='Shared-timing and gap/reset morphology provide positive contrary evidence for the selected eclipse interpretation.',limitations='No reliable target eclipse clock follows from these flags; unrelated binarity remains possible.',next='Revisit only if a stable reduction yields a target-centered repeated narrow loss.'),
'Q017':dict(verdict='REFUTED',depth='',finding='S54 raw SAP declines from about 1.6 times its sector median toward zero on both spacecraft observing orbits, with ripples through the flagged windows. S55 repeats a rising ramp followed by a sharp reset. S14/S41/S81 do not show matching clean losses. These are large extraction or detector baseline pathologies, not normalizable isolated eclipse profiles.',interpretation='Positive orbit-repeating pathological flux behavior refutes the selected eclipse windows.',limitations='No physically meaningful depth or eclipse epoch can be extracted from these segments; this does not exclude a different binary signal.',next='Check a stable independent photometric reduction before considering any eclipse timing.'),
'Q018':dict(verdict='REFUTED',depth='',finding='The S5 1444.76 and S98 4012.56 selected depressions sit within broad, evolving undulations lasting roughly days; S5 has several similarly smooth troughs and S98 has changing wave shape and data gaps. Neither selected window is a discrete repeating eclipse with measured same-kind timing.',interpretation='The observed morphology supports variable continuum rather than the selected eclipse claim. The underlying variability may be astrophysical.',limitations='No secure eclipse period, depth or source-specific geometry is measured; a different binary signal is not excluded.',next='Study the continuum variability separately; seek a narrow repeated loss before an eclipse classification.'),
'Q019':dict(verdict='REFUTED',depth='',finding='The S13 1669.05 broad selected deficit follows a 1667.572–1668.676 d gap and flux reset. S39 has multiple rapidly alternating dip/bright flags from 2368.93 to 2373.81 in a jagged segment after a 2368.010–2368.489 d gap. S94 3875.12 shares the orbit-boundary timing of Q014/Q016; the 31-sector raw overview has numerous broad ramps and steps.',interpretation='The selected events are positively explained by unstable baseline, gap and common-timing effects rather than repeated isolated eclipses.',limitations='No reliable clock or depth is established from these flags; this does not rule out another binary event.',next='Use a stable local background/reduction before considering a new repeated-event claim.'),
'Q020':dict(verdict='REFUTED',depth='',finding='Across 21 sectors the many dip and bright flags sit on long curved ramps and sharp orbit-edge steps. Examples include the S55 2809.11 dip before the 2809.907–2810.949 d gap, S58 2895.72 dip beside a 2896.021–2896.317 d discontinuity, S83 3571.39 dip before 3571.677–3571.955 d gap, and S84 3603.91 beside 3603.975–3604.195 d gap. Shapes and baseline levels change greatly between sectors.',interpretation='The selected eclipse interpretation is refuted by repeated positive gap/step/ramp context, without a stable isolated eclipse profile.',limitations='The numerous flags do not give a physical clock or depth; this does not globally exclude binarity.',next='Revisit only with consistent background removal and target-centered repeated residuals.'),
}
fields=['sample_id','tic','sample_stratum','physical_verdict','full_review_completion','novelty_status','period_days','period_error_days','primary_epoch_btjd','depth_ppt','limitations','next_check','report']
res=[]
for row in rows:
    sid=row['sample_id'];tic=row['tic']; d=R[sid];out=B/tic
    inv=out/'lead-inventory.json'; assert inv.exists()
    packet=ROOT/'source-packets'/tic/'sources.json'; pkt=json.loads(packet.read_text(encoding='utf-8'))
    inventory=json.loads(inv.read_text(encoding='utf-8'))
    assert inventory['bulk_sha256']==pkt['bulk_result_sha256']
    assert all(s['sha256'] in {v['sha256'] for v in pkt['verified_files']} for s in inventory['sectors'])
    numerical=dict(sample_id=sid,tic=tic,verdict=d['verdict'],review_scope='Selected eclipse interpretation in hash-verified cached QLP SAP, with bounded follow-up where decisive.',evidence=d['finding'],interpretation=d['interpretation'],limitations=d['limitations'],source_packet_sha256=hashlib.sha256(packet.read_bytes()).hexdigest(),inventory_sha256=hashlib.sha256(inv.read_bytes()).hexdigest(),n_sectors=len(inventory['sectors']),n_flagged_windows=sum(len(s['flagged_windows']) for s in inventory['sectors']),catalogue_status=status[sid]['novelty_status'])
    (out/'lead-review.json').write_text(json.dumps(numerical,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
    report=f"# {sid} — TIC {tic}\n\n**Physical verdict: {d['verdict']}.** Bounded review of the selected eclipse claim; full review completion: COMPLETE. **Novelty: UNKNOWN.** The exact-queue shared catalogue leaves VSX, ASAS-SN, and Kostov table 3/4 gates unavailable; prior nonmatches cannot establish novelty.\n\n## Evidence\n\n{d['finding']}\n\n{d['interpretation']}\n\n## Limits and next check\n\n{d['limitations']}\n\n{d['next']}\n\n## Reproducibility\n\n`lead-inventory.json` records the actual quality-zero, finite positive SAP ranges, >0.2-day gaps, retained windows, source paths and SHA256 hashes. `lead-raw-overview.png` shows every cached sector. `lead-review.json` records this bounded interpretation and packet hash. The batch scripts reproduce raw overviews and the Q011/Q015 deciding checks."
    if sid=='Q011':report+=' `lead-q011-clock.json`, `lead-q011-event-zooms.png`, `cutouts/lead-pixel-evidence.json`, `cutouts/lead-alt-evidence.json`, and the helper Gaia cone receipt record measured recurrence, tested null coverage, alternative extraction and capable neighbor.'
    if sid=='Q015':report+=' `cutouts/lead-pixel-evidence.json`, three WCS difference maps, and the helper Gaia cone receipt establish off-target source attribution.'
    if sid=='Q017':report+=' The independent `helper-audit.md` checks the pathological S54/S55 raw context.'
    report+='\n'
    (out/'REPORT.md').write_text(report,encoding='utf-8')
    res.append(dict(sample_id=sid,tic=tic,sample_stratum=row['sample_stratum'],physical_verdict=d['verdict'],full_review_completion='COMPLETE',novelty_status='UNKNOWN',period_days='',period_error_days='',primary_epoch_btjd='',depth_ppt=d['depth'],limitations=d['limitations'],next_check=d['next'],report=str((out/'REPORT.md').resolve())))
with (B/'RESULTS.csv').open('w',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(res)
print('wrote',len(res),'reports and RESULTS.csv')
